using UnityEngine;

namespace FormulaGame
{
    // Semantic cues share the existing SFX source and are arbitrated once per frame.
    // A successful purchase wins over the generic click generated by the same button.
    public static class FormulaAudio
    {
        // Keep the original values stable for authored sound banks.
        public enum Cue { Focus, Confirm, Record, Result, Unlock, End, Back, Error, Purchase, Equip, Countdown, Go, LapInvalid, WrongWay, FinalLap }
        private static readonly float[] lastPlayed = NewTimes();
        private static readonly int[] playedCounts = new int[(int)Cue.FinalLap + 1];
        private static Cue pendingCue;
        private static AudioClip pendingClip;
        private static int pendingFrame = -1;
        private static float navigationAfter;
        public static Cue LastPlayedCue { get; private set; }
        public static AudioClip LastPlayedClip { get; private set; }
        public static int GetPlayedCount(Cue cue) => playedCounts[(int)cue];

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset()
        {
            for (int i = 0; i < lastPlayed.Length; i++) { lastPlayed[i] = float.NegativeInfinity; playedCounts[i] = 0; }
            pendingFrame = -1; pendingClip = null; navigationAfter = -1; LastPlayedClip = null;
        }
        private static float[] NewTimes()
        {
            var times = new float[(int)Cue.FinalLap + 1];
            for (int i = 0; i < times.Length; i++) times[i] = float.NegativeInfinity;
            return times;
        }

        public static void Play(Cue cue)
        {
            if (SoundManager.Instance == null || !CanPlay(cue)) return;
            AudioClip clip = FormulaSoundBank.Current != null ? FormulaSoundBank.Current.GetCue(cue) : null;
            if (clip == null) clip = LegacyClip(cue);
            if (clip == null) return;
            if (pendingFrame >= 0 && pendingFrame != Time.frameCount) Flush();
            if (pendingFrame == Time.frameCount && Priority(cue) <= Priority(pendingCue)) return;
            pendingCue = cue; pendingClip = clip; pendingFrame = Time.frameCount;
        }

        // SoundManager calls this in LateUpdate, after UI and race state changes.
        public static void Flush()
        {
            if (pendingFrame < 0) return;
            var cue = pendingCue; var clip = pendingClip;
            pendingFrame = -1; pendingClip = null;
            if (SoundManager.Instance == null || clip == null || !CanPlay(cue)) return;
            lastPlayed[(int)cue] = Time.unscaledTime;
            if (cue != Cue.Focus) navigationAfter = Time.unscaledTime + .12f;
            LastPlayedCue = cue; LastPlayedClip = clip; playedCounts[(int)cue]++;
            SoundManager.Instance.PlaySfx(clip, Gain(cue));
        }

        public static bool IsGameplayCue(Cue cue) => cue == Cue.Record || cue == Cue.Countdown || cue == Cue.Go
            || cue == Cue.LapInvalid || cue == Cue.WrongWay || cue == Cue.FinalLap;
        private static bool CanPlay(Cue cue)
        {
            if (IsGameplayCue(cue) && (!FormulaSession.InRace || Time.timeScale <= 0 || AudioListener.pause)) return false;
            if ((cue == Cue.Focus || cue == Cue.Confirm) && Time.unscaledTime < navigationAfter) return false;
            float interval = cue == Cue.WrongWay ? 8f : cue == Cue.LapInvalid ? 2f
                : cue == Cue.Focus || cue == Cue.Confirm ? .075f : cue == Cue.Countdown ? .2f : .12f;
            return Time.unscaledTime - lastPlayed[(int)cue] >= interval;
        }
        private static int Priority(Cue cue) => cue == Cue.Focus ? 0 : cue == Cue.Confirm ? 1 : cue == Cue.Back ? 2
            : cue == Cue.Equip ? 3 : cue == Cue.Record ? 4 : cue == Cue.Purchase ? 5
            : cue == Cue.FinalLap ? 6 : cue == Cue.Error || cue == Cue.LapInvalid || cue == Cue.WrongWay ? 7 : 8;
        private static float Gain(Cue cue) => cue == Cue.Focus ? .22f : cue == Cue.Confirm || cue == Cue.Back ? .38f
            : cue == Cue.Countdown ? .5f : cue == Cue.Go ? .68f : cue == Cue.WrongWay || cue == Cue.LapInvalid ? .55f : .6f;
        private static AudioClip LegacyClip(Cue cue)
        {
            var assets = FormulaMenuAssets.Current;
            if (assets == null) return null;
            switch (cue)
            {
                case Cue.Focus: return assets.focusSound;
                case Cue.Confirm: return assets.confirmSound;
                case Cue.Record: return assets.recordSound;
                case Cue.Result: return assets.resultSound;
                case Cue.Unlock: return assets.unlockSound;
                case Cue.End: return assets.endSound;
                default: return null;
            }
        }
    }
}
